// graph_engine.cpp -- partition 0 of 2 (block split) for graph "ring50"
// AUTO-GENERATED by gen_hls_partitioned.py. Do not edit by hand.
//
// Owns 25 of 50 vertices, 50 baked OR terms. One hop per invocation;
// the host ORs this partial with the other cards' and feeds it back.
#include "graph_wire.hpp"

extern "C" void graph_engine_part(
        const gw_word_t *state_in,
        gw_word_t       *part_out,
        unsigned        *count_out,
        unsigned         nq,
        unsigned         num_steps) {
#pragma HLS INTERFACE m_axi     port=state_in  bundle=gmem0 offset=slave depth=1024
#pragma HLS INTERFACE m_axi     port=part_out  bundle=gmem1 offset=slave depth=1024
#pragma HLS INTERFACE m_axi     port=count_out bundle=gmem2 offset=slave depth=1024
#pragma HLS INTERFACE s_axilite port=state_in  bundle=control
#pragma HLS INTERFACE s_axilite port=part_out  bundle=control
#pragma HLS INTERFACE s_axilite port=count_out bundle=control
#pragma HLS INTERFACE s_axilite port=nq        bundle=control
#pragma HLS INTERFACE s_axilite port=num_steps bundle=control
#pragma HLS INTERFACE s_axilite port=return    bundle=control

    // num_steps==0 passes the state through unchanged (restricted to our
    // own bits), which is what the whole-graph engine does at k=0.
    const bool do_hop = (num_steps > 0);

    BATCH: for (unsigned q = 0; q < nq; ++q) {
#pragma HLS PIPELINE II=1
        ap_uint<1> s[GW_N];
#pragma HLS ARRAY_PARTITION variable=s complete dim=1
        LOADQ: for (unsigned w = 0; w < GW_NW; ++w) {
#pragma HLS UNROLL
            gw_word_t word = state_in[q * GW_NW + w];
            for (unsigned b = 0; b < GW_WORD_BITS; ++b) {
#pragma HLS UNROLL
                unsigned idx = w * GW_WORD_BITS + b;
                if (idx < GW_N) s[idx] = word[b];
            }
        }

        // Full width so the cross-card combine is a plain OR; every bit
        // we do not own stays 0.
        ap_uint<1> res[GW_N];
#pragma HLS ARRAY_PARTITION variable=res complete dim=1
        ZERO: for (unsigned v = 0; v < GW_N; ++v) {
#pragma HLS UNROLL
            res[v] = 0;
        }

        // ===== baked wiring: this partition's rows only =====
        res[0] = do_hop ? (s[0] | s[1] | s[49]) : s[0];
        res[1] = do_hop ? (s[1] | s[0] | s[2]) : s[1];
        res[2] = do_hop ? (s[2] | s[1] | s[3]) : s[2];
        res[3] = do_hop ? (s[3] | s[2] | s[4]) : s[3];
        res[4] = do_hop ? (s[4] | s[3] | s[5]) : s[4];
        res[5] = do_hop ? (s[5] | s[4] | s[6]) : s[5];
        res[6] = do_hop ? (s[6] | s[5] | s[7]) : s[6];
        res[7] = do_hop ? (s[7] | s[6] | s[8]) : s[7];
        res[8] = do_hop ? (s[8] | s[7] | s[9]) : s[8];
        res[9] = do_hop ? (s[9] | s[8] | s[10]) : s[9];
        res[10] = do_hop ? (s[10] | s[9] | s[11]) : s[10];
        res[11] = do_hop ? (s[11] | s[10] | s[12]) : s[11];
        res[12] = do_hop ? (s[12] | s[11] | s[13]) : s[12];
        res[13] = do_hop ? (s[13] | s[12] | s[14]) : s[13];
        res[14] = do_hop ? (s[14] | s[13] | s[15]) : s[14];
        res[15] = do_hop ? (s[15] | s[14] | s[16]) : s[15];
        res[16] = do_hop ? (s[16] | s[15] | s[17]) : s[16];
        res[17] = do_hop ? (s[17] | s[16] | s[18]) : s[17];
        res[18] = do_hop ? (s[18] | s[17] | s[19]) : s[18];
        res[19] = do_hop ? (s[19] | s[18] | s[20]) : s[19];
        res[20] = do_hop ? (s[20] | s[19] | s[21]) : s[20];
        res[21] = do_hop ? (s[21] | s[20] | s[22]) : s[21];
        res[22] = do_hop ? (s[22] | s[21] | s[23]) : s[22];
        res[23] = do_hop ? (s[23] | s[22] | s[24]) : s[23];
        res[24] = do_hop ? (s[24] | s[23] | s[25]) : s[24];
        // ===== end baked wiring =====

        unsigned c = 0;
        CNT: for (unsigned v = 0; v < GW_N; ++v) {
#pragma HLS UNROLL
            c += (unsigned) res[v];
        }
        count_out[q] = c;

        STOREQ: for (unsigned w = 0; w < GW_NW; ++w) {
#pragma HLS UNROLL
            gw_word_t word = 0;
            for (unsigned b = 0; b < GW_WORD_BITS; ++b) {
#pragma HLS UNROLL
                unsigned idx = w * GW_WORD_BITS + b;
                if (idx < GW_N) word[b] = res[idx];
            }
            part_out[q * GW_NW + w] = word;
        }
    }
}
